import {orderPlacements,groundRoot,spriteFrame,clipFor} from '../resources/browser/sprite-layout.js';
import {worldRasterPlan,paintWorldRaster} from '../resources/browser/world-sprite-raster.js';
const inputs=await(await fetch('../resources/browser/inputs.json')).json(),objects=inputs.objects,by=new Map(objects.map(o=>[o.id,o])),NS='http://www.w3.org/2000/svg';const url=p=>new URL(p,location.href).href,cache=new Map();async function image(u){if(cache.has(u))return cache.get(u);const i=new Image();i.src=u;await i.decode();cache.set(u,i);return i}function el(n,a={}){const e=document.createElementNS(NS,n);for(const[k,v]of Object.entries(a))e.setAttribute(k,v);return e}
function place(asset,p,d,anchor,phase=0,clip='static'){const o=by.get(asset),r=o.directionRootCells?.[d]||o.rootCell||o.footprint.map(x=>x/2),a={N:Math.PI,E:Math.PI/2,S:0,W:-Math.PI/2}[d],x=Math.cos(a)*p[0]-Math.sin(a)*p[1],y=Math.sin(a)*p[0]+Math.cos(a)*p[1];return{object:asset,direction:d,clip,x:anchor[0]/128+x-r[0],y:anchor[1]/128-y-r[1],offset:[phase,phase-89.6*p[2]]}}
function spritesFor(c){const d=c.direction,phase=c.phase||0,anchor=c.anchor||[384,440];let items=[];if(c.kind==='standalone')items=[place('workshop-hut',[0,0,0],d,c.anchor||[96,352],phase)];else if(c.kind==='repeat'){for(let y=0;y<2;y++)for(let x=0;x<2;x++)items.push(place('workshop-hut',[0,0,0],d,[96+x*220,352+y*250],phase))}else{items=[place('dock-floor',[0,0,0],d,anchor,phase),place('workshop-hut',[.78,.35,.23],d,anchor,phase)];if(c.kind!=='support'){items.push(place('dock-entry',[0,-1.5,0],d,anchor,phase));items.push(place('submarine-yellow',[-.7,-.42,.23],d,anchor,phase,'dock-ready'))}if(c.human)items.push({...place('customer-rosa',c.human,d,anchor,phase,'stand'),direction:{N:'S',S:'N',E:'W',W:'E'}[d]});if(c.cover)items.push(place('dock-cover',[0,0,.23],d,anchor,phase,c.cover))}items=items.map((p,i)=>({...p,id:p.object==='dock-floor'?'dock-deck':`${p.object}-${i}`}));const deck=items.find(p=>p.object==='dock-floor');for(const p of items){if(deck&&['workshop-hut','submarine-yellow'].includes(p.object))p.supportedBy='dock-deck';if(p.object==='customer-rosa'&&c.human){const[x,y]=c.human;if(Math.abs(x)<=1.5&&y>=-1.5&&y<=1.5)p.supportedBy='dock-deck'}}const ordered=orderPlacements(items,objects);return{placements:items,order:ordered.map(p=>p.object),sprites:ordered.map(p=>{const o=by.get(p.object),f=spriteFrame(o,clipFor(o,p.clip),p.direction,0);let path='../resources/browser/'+f.image;if(p.object==='dock-cover')path=`../resources/browser/dock-cover-${c.cover}-${d}-${String(c.coverIndex||0).padStart(2,'0')}.png`;const[x,y]=groundRoot(p,o);return{url:url(path),rect:f.rect,x:x-f.root[0],y:y-f.root[1],width:f.frameSize[0],height:f.frameSize[1],object:p.object}})}}
window.renderCases=async function(cases){document.querySelector('#root').replaceChildren();const records=[];window.lastCanvases=[];for(const c of cases){const frame=c.frame||[768,768],bounds=c.bounds||[0,0,...frame],zoom=c.zoom??1,panel=document.createElement('div');panel.className='panel';const label=document.createElement('div');label.className='label';label.textContent=c.label||JSON.stringify(c);panel.append(label);const stage=document.createElement('div');stage.className='stage';stage.style.width=bounds[2]*zoom+'px';stage.style.height=bounds[3]*zoom+'px';stage.style.background=c.background||'#a7a7a7';const svg=el('svg',{viewBox:bounds.join(' '),width:bounds[2]*zoom,height:bounds[3]*zoom});let record,sprites;if(c.native){const name=c.kind==='human'?`approved-human-${c.direction}-${c.humanIndex||0}`:c.cover?`old-cover-${c.cover}-${c.direction}-${String(c.coverIndex||0).padStart(2,'0')}`:c.kind==='support'?`support-${c.direction}`:`family-${c.direction}`;record={order:['depth-tested-native'],placements:[]};sprites=[{url:url(`../../candidates/round-01/contexts/${name}.png`),rect:[0,0,frame[0]*2,frame[1]*2],x:c.phase||0,y:c.phase||0,width:frame[0],height:frame[1]}]}else{record=spritesFor(c);sprites=record.sprites}const plan=worldRasterPlan(sprites,bounds),canvas=document.createElement('canvas');paintWorldRaster(canvas,plan,await Promise.all(sprites.map(s=>image(s.url))));const fo=el('foreignObject',{x:plan.x,y:plan.y,width:plan.width/plan.scale,height:plan.height/plan.scale});fo.append(canvas);svg.append(fo);stage.append(svg);panel.append(stage);document.querySelector('#root').append(panel);window.lastCanvases.push({canvas,plan,bounds});records.push({...c,placements:record.placements,order:record.order,plan:{...plan,sprites:plan.sprites.map(s=>({...s,url:s.url.replace(location.origin,'')}))},imageSmoothingEnabled:canvas.getContext('2d').imageSmoothingEnabled})}await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));return records};window.exportRaster=function(index){const{canvas,plan,bounds}=window.lastCanvases[index],out=document.createElement('canvas');out.width=bounds[2]*plan.scale;out.height=bounds[3]*plan.scale;out.getContext('2d').putImageData(canvas.getContext('2d').getImageData(Math.round((bounds[0]-plan.x)*plan.scale),Math.round((bounds[1]-plan.y)*plan.scale),out.width,out.height),0,0);return out.toDataURL('image/png')};window.ready=true;
